import{_ as a,o as i,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Days Asia- Performance experiments and usage tips about RGW object listing","description":"","frontmatter":{"title":"Ceph Days Asia- Performance experiments and usage tips about RGW object listing","date":"2024-10-04T00:00:00.000Z","updated":"2024-10-04T00:00:00.000Z","tags":["Ceph","RGW","Object storage","Performance optimization","Ceph Days Asia"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_Days_Asia_-_Performance_experiments_and_usage_tips_about_RGW_object_listing.md","filePath":"posts/2024/Ceph_Days_Asia_-_Performance_experiments_and_usage_tips_about_RGW_object_listing.md","lastUpdated":1780459816000}'),s={name:"posts/2024/Ceph_Days_Asia_-_Performance_experiments_and_usage_tips_about_RGW_object_listing.md"};function o(r,e,n,_,p,c){return i(),t("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要-rgw对象列表查询性能实验" tabindex="-1">会议纪要：RGW对象列表查询性能实验 <a class="header-anchor" href="#会议纪要-rgw对象列表查询性能实验" aria-label="Permalink to &quot;会议纪要：RGW对象列表查询性能实验&quot;">​</a></h3><h4 id="会议背景" tabindex="-1">会议背景 <a class="header-anchor" href="#会议背景" aria-label="Permalink to &quot;会议背景&quot;">​</a></h4><p>本次Ceph Days Asia会议中，一位来自大数据公司的存储领域专家主持了关于Ceph分布式存储系统中RGW（RADOS Gateway）对象列表查询性能的实验及其结果应用的讨论。</p><h4 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h4><ol><li><p><strong>实验动机</strong></p><ul><li>随着对象数量的增加，对象列表查询时间显著增加，这是对象存储系统的已知弱点。</li><li>通过实验分析不同对象数量下的列表查询性能，寻求解决方案。</li></ul></li><li><p><strong>背景知识</strong></p><ul><li>使用S3 API中的List Object接口，这是一个RESTful API，用于检索S3对象列表。</li><li>关注参数<code>max-keys</code>和<code>prefix</code>，影响查询效率和返回对象数量。</li></ul></li><li><p><strong>实验设计</strong></p><ul><li>定义两种列表查询方式：普通列表查询（不使用前缀）和选择性列表查询（使用前缀）。</li><li>实验环境包含10,000个对象，对象带有前缀以便于选择性查询。</li><li>测量不同对象数量和请求数量下的查询性能。</li></ul></li><li><p><strong>实验结果</strong></p><ul><li>随着请求数量增加，查询时间显著增加，对象数量增加对查询时间影响较小。</li><li>选择性列表查询比普通列表查询多花费约1.2倍的时间。</li></ul></li><li><p><strong>结果分析与使用建议</strong></p><ul><li>增加单个请求的负载量可优化性能。</li><li>调整RGW配置参数<code>rgw max-list</code>，增加单个请求返回对象数量，减少请求次数。</li><li>尽管前缀查询增加开销，但通过减少目标和请求次数，仍能有效提升性能。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>优化RGW配置，特别是增加<code>rgw max-list</code>值，以减少查询时间和请求次数。</li><li>探索改进查询算法或增加缓存机制等优化方法。</li></ul></li></ol><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>本次会议通过实验和分析，提供了一系列关于优化RGW对象列表查询性能的实用建议和后续行动计划，旨在提升Ceph存储系统的整体性能和用户体验。</p><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在专家的感谢和与会者的掌声中圆满结束。</p>',9)])])}const h=a(s,[["render",o]]);export{u as __pageData,h as default};
